 *
 * @param array the long array to obtain a hash code
 * @return the long array's hash code, which could be 0 if the array is null.
 */
public static int nullSafeHashCode(long[] array) {
    // check if the array is null
    if (array == null) {
        return 0;
    }

    // initialize a hash code variable
    int hashCode = 1;

    // loop through the array and calculate the hash code
    for (long element : array) {
        hashCode = 31 * hashCode + (int) (element ^ (element >>> 32));
    }

    // return the hash code
    return hashCode;
}

