    Calendar cal = Calendar.getInstance();
    cal.setTimeInMillis(timeBucket);
    int currentDayOfWeek = cal.get(Calendar.DAY_OF_WEEK);
    int currentDayPeriod = (int) (timeBucket % (24 * 60 * 60 * 1000));

    // 2. Adjust the current day of the week and time period based on the dayStep
    int newDayOfWeek = currentDayOfWeek - currentDayOfWeek % dayStep;
    int newTimePeriod = currentDayPeriod - (currentDayPeriod % (24 * 60 * 60 * 1000) / dayStep);

    // 3. Re-format the time bucket with the new day of the week and time period
    Calendar newCal = Calendar.getInstance();
    newCal.set(Calendar.DAY_OF_WEEK, newDayOfWeek);
