    newCal.set(Calendar.MINUTE, 0);
    newCal.set(Calendar.SECOND, 0);
    newCal.set(Calendar.MILLISECOND, 0);
    newCal.add(Calendar.MILLISECOND, newTimePeriod);
    return newCal.getTimeInMillis();
