/**
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
public void pop(String descriptor) {
    while (true) {
        final Type type = Type.getType(descriptor);
        if (type != null && Type.VOID != type) {
            popType(type);
        } else {
            break;
        }
    }
}

void popType(Type type) {
    final AbstractType resultType = AbstractType.get(type);
    if (resultType == null) {
        throw new IllegalArgumentException("Unsupported type: " + type);
    }
    for (int i = 0; i < resultType.getSize(); i++) {
        final AbstractType pushedType = getCurrentFrame().pop();
        if (!pushedType.isAssignableTo(resultType)) {
            throw new IllegalStateException("Type mismatch: expected " + resultType + " but got " + pushedType);
        }
    }
}

/**
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        // Handle method descriptor
        final int numArguments = descriptor.length() - 1;
        for (int i = 0; i < numArguments; i++) {
            pop();
        }
    } else {
        // Handle type descriptor
        final String type = descriptor;
        if (type.equals("L")) {
            // Reference type - pop Long
            pop();
        } else if (type.equals("I")) {
            // Integer type - pop Int
            pop();
        } else if (type.equals("F")) {
            // Float type - pop Float
            pop();
        } else if (type.equals("D")) {
            // Double type - pop Double
            pop();
        } else if (type.equals("J")) {
            // Long type - pop Long
            pop();
        } else if (type.equals("V")) {
            // Void type - do nothing
        } else {
            throw new IllegalStateException("Invalid type descriptor: " + type);
        }
    }
}

