void pop(String descriptor){
    // Parse the descriptor to determine the number of types to pop
    int numTypes = 0;
    if (descriptor.startsWith("(")) { // Method descriptor
        int start = descriptor.indexOf(")") + 1;
        int end = descriptor.indexOf(")");
        numTypes = 1; // Return type
        for (int i = start; i < end; i++) {
            if (descriptor.charAt(i) == 'L') { // Class type
                numTypes++;
            }
        }
    } else { // Type descriptor
        numTypes = 1;
    }

    // Pop the necessary types from the output frame stack
    while (numTypes > 0) {
        outputFrameStack.pop();
        numTypes--;
    }
}

