private List<Pair<Integer,Integer>> computeMinimalSeparators(E e) {
    // Get the vertices of the given edge
    int v1 = graph.getEdgeSource(e);
    int v2 = graph.getEdgeTarget(e);

    // The list of minimal separators for the given edge
    List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

