 private static ThreadSnapshot parseThreadSnapshot(String line) {
    String[] fields = line.split(" ");
    long time = Long.parseLong(fields[0]);
    int threadId = Integer.parseInt(fields[1]);
    String threadName = fields[2];

    List<StackTrace> stackTraces = new ArrayList<>();
    for (int i = 3; i < fields.length; i += 3) {
        String className = fields[i];
        String methodName = fields[i + 1];
        int lineNumber = Integer.parseInt(fields[i + 2]);
        stackTraces.add(new StackTrace(className, methodName, lineNumber));
    }

    return new ThreadSnapshot(time, threadId, threadName, stackTraces);
}

