public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("S#")) {
                // Parse the stack trace
                StackTraceElement[] stackTrace = parseStackTrace(line);

                // Check if the line belongs to one of the time ranges
                long startTime = Long.parseLong(line.substring(line.indexOf("|") + 1, line.indexOf("|") + 3));
                long endTime = Long.parseLong(line.substring(line.lastIndexOf("|") + 1));
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (startTime >= timeRange.getStartTime() && startTime <= timeRange.getEndTime()) {
                        inRange = true;
                        break;
                    }
                    if (endTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
                        inRange = true;
                        break;
                    }
                }

                if (inRange) {
                    // Create a new ThreadSnapshot object
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot(stackTrace, startTime, endTime);
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
    }

    return threadSnapshots;
}

/** 
 * Parse the stack trace from a line
 */
public static StackTraceElement[] parseStackTrace(String line) throws IOException {
    StackTraceElement[] stackTrace = new StackTraceElement[line.length() - 4];
    for (int i = 0; i < stackTrace.length; i++) {
        int index = line.indexOf("|", i + 2);
        stackTrace[i] = new StackTraceElement(line.substring(0, index + 1), line.substring(index + 1));
    }
    return stackTrace;
}
